import std.collection.HashMap
import std.time.DateTime
import std.logging

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        /*
        Filter the incoming request based on certain rules and conditions.
        :param request: HashMap<String, Any>, the incoming request details
        :return: Bool, true if the request is allowed, false otherwise
        >>> filter = AccessGatewayFilter()
        >>> filter.filter(HashMap<String, Any>([('path', '/login'), ('method', 'POST')]))
        true
        */
        let request_uri: String = request['path'] as String
        let method: String = request['method'] as String

        if self.is_start_with(request_uri: request_uri) {
            return true
        }

        match self.get_jwt_user(request: request) {
            Some(token) => {
                let user: HashMap<String, Any> = token['user'] as HashMap<String, Any>
                if (user['level'] as Int) > 2 {
                    self.set_current_user_info_and_log(user: user)
                    return true
                } else {
                    return false
                }
            }
            None => return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        /*
        Check if the request URI starts with certain prefixes.
        Currently, the prefixes being checked are "/api" and "/login".
        :param request_uri: String, the URI of the request
        :return: Bool, true if the URI starts with certain prefixes, false otherwise
        >>> filter = AccessGatewayFilter()
        >>> filter.is_start_with('/api/data')
        true
        */
        let start_with: Array<String> = ["/api", "/login"]
        for s in start_with {
            if request_uri.startswith(s) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        /*
        Get the user information from the JWT token in the request.
        :param request: HashMap<String, Any>, the incoming request details
        :return: HashMap<String, Any> or None, the user information if the token is valid, None otherwise
        >>> filter = AccessGatewayFilter()
        >>> filter.get_jwt_user(HashMap<String, Any>([('headers', HashMap<String, Any>([('Authorization', HashMap<String, Any>([('user', HashMap<String, Any>([('name', 'user1')])), ('jwt', 'user1'+DateTime.now().format("yyyy-MM-dd"))]))]))]))
        {'user': {'name': 'user1'}
        */
        let headers: HashMap<String, Any> = request['headers'] as HashMap<String, Any>
        let token_map: HashMap<String, Any> = headers['Authorization'] as HashMap<String, Any>
        let token: HashMap<String, Any> = token_map

        let user: HashMap<String, Any> = token['user'] as HashMap<String, Any>
        let jwt: String = token['jwt'] as String

        if jwt.startswith(user['name'] as String) {
            let jwt_parts: Array<String> = jwt.split(user['name'] as String)
            if jwt_parts.length > 1 {
                let jwt_str_date: String = jwt_parts[1]
                let jwt_date: DateTime = DateTime.parse(jwt_str_date, "yyyy-MM-dd")
                let today: DateTime = DateTime.now()
                if today - jwt_date >= 3 {
                    return None
                }
            } else {
                return None
            }
        } else {
            return None
        }
        return Some(token)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        /*
        Set the current user information and log the access.
        :param user: HashMap<String, Any>, the user information
        :return: Unit
        >>> filter = AccessGatewayFilter()
        >>> user = HashMap<String, Any>([('name', 'user1'), ('address', '127.0.0.1')])
        >>> filter.set_current_user_info_and_log(user: user)
        */
        let name: String = user['name'] as String
        let host: String = user['address'] as String
        let now: DateTime = DateTime.now()
        logging.log(msg: name + host + now.format("yyyy-MM-dd HH:mm:ss"), level: 1)
    }
}

import std.math.*

class AreaCalculator {
    /*
    This is a class for calculating the area of different shapes, including circle, sphere, cylinder, sector and annulus.
    */

    let radius: Float64

    public init(radius: Float64) {
        /*
        Initialize the radius for shapes.
        :param radius: Float64
        */
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        /*
        calculate the area of circle based on this.radius
        :return: area of circle, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_circle_area()
        12.566370614359172
        */
        return PI * this.radius * this.radius
    }

    public func calculate_sphere_area(): Float64 {
        /*
        calculate the area of sphere based on this.radius
        :return: area of sphere, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_sphere_area()
        50.26548245743669
        */
        return 4.0 * PI * this.radius * this.radius
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        /*
        calculate the area of cylinder based on this.radius and height
        :param height: height of cylinder, Float64
        :return: area of cylinder, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_cylinder_area(3.0)
        62.83185307179586
        */
        return 2.0 * PI * this.radius * (this.radius + height)
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        /*
        calculate the area of sector based on this.radius and angle
        :param angle: angle of sector, Float64
        :return: area of sector, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_sector_area(3.1415926)
        6.283185307179586
        */
        return this.radius * this.radius * angle / 2.0
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        /*
        calculate the area of annulus based on inner_radius and out_radius
        :param inner_radius: inner radius of sector, Float64
        :param outer_radius: outer radius of sector, Float64
        :return: area of annulus, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_annulus_area(2.0, 3.0)
        15.707963267948966
        */
        return PI * (outer_radius * outer_radius - inner_radius * inner_radius)
    }
}

