class Classroom {
    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        if !this.courses.contains(course) {
            this.courses.add(course)
        }
    }

    public func remove_course(course: Course): Unit {
        if this.courses.contains(course) {
            for i in 0..<this.courses.size() {
                if this.courses.get(i) == course {
                    this.courses.remove_at(i)
                    break
                }
            }
        }
    }

    public func is_free_at(check_time: String): Bool {
        let check_dt = DateTime.parse(check_time, "yyyy/MM/dd HH:mm")
        for course in this.courses {
            let start_dt = DateTime.parse(course.start_time, "yyyy/MM/dd HH:mm")
            let end_dt = DateTime.parse(course.end_time, "yyyy/MM/dd HH:mm")
            if start_dt <= check_dt && check_dt <= end_dt {
                return false
            }
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        let new_start = DateTime.parse(new_course.start_time, "yyyy/MM/dd HH:mm")
        let new_end = DateTime.parse(new_course.end_time, "yyyy/MM/dd HH:mm")
        for course in this.courses {
            let start = DateTime.parse(course.start_time, "yyyy/MM/dd HH:mm")
            let end = DateTime.parse(course.end_time, "yyyy/MM/dd HH:mm")
            if (start <= new_start && new_start <= end) || (start <= new_end && new_end <= end) {
                return false
            }
        }
        return true
    }
}

