    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for i in 0..<this.data.length() {
            sum += this.data.get(i)
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        var min_val: Float64 = this.data.get(0)
        for i in 1..<this.data.length() {
            if this.data.get(i) < min_val {
                min_val = this.data.get(i)
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        var max_val: Float64 = this.data.get(0)
        for i in 1..<this.data.length() {
            if this.data.get(i) > max_val {
                max_val = this.data.get(i)
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
