import std.math.pi

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        var sum1: Float64 = 0.0
        for x in data1 {
            sum1 += x
        }
        let mean1 = sum1 / n

        var sum2: Float64 = 0.0
        for x in data2 {
            sum2 += x
        }
        let mean2 = sum2 / n

        var numerator: Float64 = 0.0
        for i in range(0, n) {
            numerator += (data1.get(i) - mean1) * (data2.get(i) - mean2)
        }

        var sum_sq1: Float64 = 0.0
        for i in range(0, n) {
            sum_sq1 += pow(data1.get(i) - mean1, 2)
        }

        var sum_sq2: Float64 = 0.0
        for i in range(0, n) {
            sum_sq2 += pow(data2.get(i) - mean2, 2)
        }

        let denominator = sqrt(sum_sq1) * sqrt(sum_sq2)
        return denominator != 0 ? numerator / denominator : 0
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        var sum: Float64 = 0.0
        for x in data {
            sum += x
        }
        let mean = sum / n

        var variance_sum: Float64 = 0.0
        for x in data {
            variance_sum += pow(x - mean, 2)
        }
        let variance = variance_sum / n
        let std_deviation = sqrt(variance)

        if std_deviation == 0 {
            return 0
        }

        var skewness_sum: Float64 = 0.0
        for x in data {
            skewness_sum += pow(x - mean, 3)
        }
        let skewness = (skewness_sum * n) / ((n - 1) * (n - 2) * pow(std_deviation, 3))
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        var sum: Float64 = 0.0
        for x in data {
            sum += x
        }
        let mean = sum / n

        var variance_sum: Float64 = 0.0
        for x in data {
            variance_sum += pow(x - mean, 2)
        }
        let std_dev = sqrt(variance_sum / n)

        if std_dev == 0 {
            return NaN  // Note: Cangjie might use different NaN handling
        }

        let centered_data: ArrayList<Float64> = ArrayList()
        for x in data {
            centered_data.add(x - mean)
        }

        var fourth_moment_sum: Float64 = 0.0
        for x in centered_data {
            fourth_moment_sum += pow(x, 4)
        }
        let fourth_moment = fourth_moment_sum / n

        let kurtosis_value = (fourth_moment / pow(std_dev, 4)) - 3
        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let coefficient = 1.0 / (sigma * sqrt(2 * pi))
        for x in data {
            let exponent = -0.5 * pow((x - mu) / sigma, 2)
            let pdf_value = coefficient * exp(exponent)
            result.add(pdf_value)
        }
        return result
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'
        */
        var plaintext: String = ""
        for char in ciphertext.chars() {
            if char.isAlpha() {
                var ascii_offset: Int64 = 0
                var c: Char = char
                if char.isUpper() {
                    ascii_offset = 65
                } else {
                    ascii_offset = 97
                    c = char.lower()
                }
                var shifted: Int64 = (c.toUnicode() - ascii_offset - shift) % 26
                if shifted < 0 {
                    shifted += 26
                }
                var new_char: Char = Char.fromUnicode(shifted + ascii_offset)
                if char.isUpper() {
                    new_char = new_char.upper()
                }
                plaintext += new_char.toString()
            } else {
                plaintext += char.toString()
            }
        }
        return plaintext
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'
        */
        var decrypted_text: String = ""
        var key_index: Int64 = 0
        for char in ciphertext.chars() {
            if char.isAlpha() {
                var k_char: Char = this.key[(key_index % this.key.length() as Int64).toInt()].lower()
                var shift: Int64 = k_char.toUnicode() - 'a'.toUnicode()
                var c: Char = char.lower()
                var decrypted_char_unicode: Int64 = (c.toUnicode() - 'a'.toUnicode() - shift) % 26
                if decrypted_char_unicode < 0 {
                    decrypted_char_unicode += 26
                }
                var decrypted_char: Char = Char.fromUnicode(decrypted_char_unicode + 'a'.toUnicode())
                if char.isUpper() {
                    decrypted_char = decrypted_char.upper()
                }
                decrypted_text += decrypted_char.toString()
                key_index += 1
            } else {
                decrypted_text += char.toString()
            }
        }
        return decrypted_text
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'
        */
        var fence: ArrayList<ArrayList<Char>> = ArrayList()
        for i in 0..rails {
            var row: ArrayList<Char> = ArrayList()
            for j in 0..encrypted_text.length() {
                row.add('\n')
            }
            fence.add(row)
        }
        var direction: Int64 = -1
        var row: Int64 = 0
        var col: Int64 = 0
        for _ in 0..encrypted_text.length() {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }
            fence[row][col] = '\0'
            col += 1
            row += direction
        }
        var index: Int64 = 0
        for i in 0..rails {
            for j in 0..encrypted_text.length() {
                if fence[i][j] == '\0' {
                    if index < encrypted_text.length() {
                        fence[i][j] = encrypted_text[(index as Int64).toInt()]
                        index += 1
                    }
                }
            }
        }
        var plain_text: String = ""
        direction = -1
        row = 0
        col: Int64 = 0
        for _ in 0..encrypted_text.length() {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }
            plain_text += fence[row][col].toString()
            col += 1
            row += direction
        }
        return plain_text
    }
}

