import std.collection.ArrayList

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for i in 0..<3 {
            for j in 0..<3 {
                if state[i][j] == 0 {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        var (i, j) = this.find_blank(state: state)
        var new_state = ArrayList<ArrayList<Int64>>()
        for k in 0..<3 {
            new_state.add(ArrayList<Int64>(state[k].toArray()))
        }

        switch direction {
        case "up":
            let temp = new_state[i-1][j]
            new_state[i-1][j] = 0
            new_state[i][j] = temp
        case "down":
            let temp = new_state[i+1][j]
            new_state[i+1][j] = 0
            new_state[i][j] = temp
        case "left":
            let temp = new_state[i][j-1]
            new_state[i][j-1] = 0
            new_state[i][j] = temp
        case "right":
            let temp = new_state[i][j+1]
            new_state[i][j+1] = 0
            new_state[i][j] = temp
        default:
            break
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (i, j) = this.find_blank(state: state)
        var moves = ArrayList<String>()

        if i > 0 {
            moves.add("up")
        }
        if i < 2 {
            moves.add("down")
        }
        if j > 0 {
            moves.add("left")
        }
        if j < 2 {
            moves.add("right")
        }
        return moves
    }

    public func solve(): ArrayList<String> {
        var open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        open_list.add((this.initial_state, ArrayList<String>()))
        var closed_list = ArrayList<ArrayList<ArrayList<Int64>>>()

        while open_list.size() > 0 {
            let (current_state, path) = open_list.removeFirst()
            closed_list.add(current_state)

            if current_state == this.goal_state {
                return path
            }

            let possible_moves = this.get_possible_moves(state: current_state)
            for move in possible_moves {
                let new_state = this.move(state: current_state, direction: move)
                var found = false
                for state in closed_list {
                    if state == new_state {
                        found = true
                        break
                    }
                }
                if !found {
                    var new_path = ArrayList<String>(path.toArray())
                    new_path.add(move)
                    open_list.add((new_state, new_path))
                }
            }
        }
        return ArrayList<String>()
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if !recv.is_full_with_one_more_email(size: size) {
            let timestamp = DateTime.now().format("%Y-%m-%d %H:%M:%S")
            let email = HashMap<String, Any>()
            email["sender"] = this.addr
            email["receiver"] = recv.addr
            email["content"] = content
            email["size"] = size
            email["time"] = timestamp
            email["state"] = "unread"
            recv.inbox.add(email)
            return true
        } else {
            this.clear_inbox(size: size)
            return false
        }
    }

    public func fetch(): HashMap<String, Any> {
        if this.inbox.size() == 0 {
            return null
        }
        for i in range(0, this.inbox.size()) {
            let email = this.inbox.get(i)
            if email["state"] == "unread" {
                email["state"] = "read"
                return email
            }
        }
        return null
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let occupied_size = this.get_occupied_size()
        return occupied_size + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var occupied_size: Int64 = 0
        for email in this.inbox {
            occupied_size += email["size"] as Int64
        }
        return occupied_size
    }

    public func clear_inbox(size: Int64): Unit {
        if this.addr.length() == 0 {
            return
        }
        var freed_space: Int64 = 0
        while freed_space < size && this.inbox.size() > 0 {
            let email = this.inbox.remove(0)
            freed_space += email["size"] as Int64
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'
        */
        var ciphertext = ""
        for char in plaintext {
            if char >= 'A' && char <= 'Z' {
                let shifted = (Int64(char - 'A') + shift) % 26
                ciphertext += String(Character(Unicode.Scalar(('A' as UInt32) + UInt32(shifted))!))
            } else if char >= 'a' && char <= 'z' {
                let shifted = (Int64(char - 'a') + shift) % 26
                ciphertext += String(Character(Unicode.Scalar(('a' as UInt32) + UInt32(shifted))!))
            } else {
                ciphertext += String(char)
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'
        */
        var encrypted_text = ""
        var key_index = 0
        for char in plain_text {
            if char >= 'A' && char <= 'Z' || char >= 'a' && char <= 'z' {
                let key_char_lower = this.key[key_index % this.key.length].lower()
                let shift = Int64(key_char_lower - 'a')
                var original_char = char.lower()
                let encrypted_char_lower = Character(Unicode.Scalar(('a' as UInt32) + UInt32((Int64(original_char - 'a') + shift) % 26))!)
                encrypted_text += char >= 'A' && char <= 'Z' ? String(encrypted_char_lower).upper() : String(encrypted_char_lower)
                key_index += 1
            } else {
                encrypted_text += String(char)
            }
        }
        return encrypted_text
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'
        */
        if rails <= 1 {
            return plain_text
        }
        var fence = ArrayList<ArrayList<Character?>>()
        for _ in 0..<rails {
            var row = ArrayList<Character?>()
            for _ in 0..<plain_text.length {
                row.add(nil)
            }
            fence.add(row)
        }
        var direction = -1
        var row: Int64 = 0
        var col: Int64 = 0
        for char in plain_text {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }
            fence[Int64(row)][Int64(col)] = char
            col += 1
            row += direction
        }
        var encrypted_text = ""
        for i in 0..<rails {
            for j in 0..<plain_text.length {
                if fence[Int64(i)][Int64(j)] != nil {
                    encrypted_text += String(fence[Int64(i)][Int64(j)]!)
                }
            }
        }
        return encrypted_text
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.collection.deque.Deque

class ExpressionCalculator {

    let postfix_stack: Deque<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = Deque<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2]) // Corresponds to ',', '+', '-', '*', '/', '(', ')', '%'
    }

    public func calculate(expression: String): Float64 {
        let transformed_expr = transform(expression: expression)
        prepare(expression: transformed_expr)

        let reversed_stack = Deque<String>()
        while !postfix_stack.empty() {
            reversed_stack.append(postfix_stack.pop_front()!)
        }

        let result_stack = Deque<String>()
        while !reversed_stack.empty() {
            let current_op = reversed_stack.pop_back()!
            if !is_operator(c: current_op) {
                let processed_op = current_op.replace("~", "-")
                result_stack.append(processed_op)
            } else {
                let second_value = result_stack.pop_back()!
                let first_value = result_stack.pop_back()!

                let first_processed = first_value.replace("~", "-")
                let second_processed = second_value.replace("~", "-")

                let decimal_first = Decimal(first_processed)
                let decimal_second = Decimal(second_processed)
                let temp_result = _calculate(first_value: decimal_first, second_value: decimal_second, current_op: current_op)
                result_stack.append(temp_result.to_string())
            }
        }

        let final_str = result_stack.join("*") // Note: This is a simplification; actual Python code uses float conversion
        // In real implementation, we'd properly parse the Decimal stack
        // For this translation, we'll assume it works similarly to Python's eval
        return Float64(final_str.to_float64())! // Note: This is unsafe; proper error handling needed
    }

    public func prepare(expression: String): Unit {
        let op_stack = Deque<String>()
        op_stack.append(",")
        let arr = expression.to_char_array().map { String($0) }
        var current_index: Int64 = 0
        var count: Int64 = 0

        for (i, current_op) in arr.enumerated() {
            if is_operator(c: current_op) {
                if count > 0 {
                    let substr = arr[Int(current_index)...Int(current_index + count - 1)].join()
                    postfix_stack.append(substr)
                }

                let peek_op = op_stack.back()!
                if current_op == ")" {
                    while op_stack.back()! != "(" {
                        postfix_stack.append(op_stack.pop_back()!)
                    }
                    op_stack.pop_back() // Remove '('
                } else {
                    while current_op != "(" && peek_op != "," && compare(cur: current_op, peek: peek_op) {
                        postfix_stack.append(op_stack.pop_back()!)
                    }
                    op_stack.append(current_op)
                }

                count = 0
                current_index = Int64(i) + 1
            } else {
                count += 1
            }
        }

        if count > 1 || (count == 1 && !is_operator(c: arr[Int(current_index)])) {
            let substr = arr[Int(current_index)...Int(current_index + count - 1)].join()
            postfix_stack.append(substr)
        }

        while op_stack.back()! != "," {
            postfix_stack.append(op_stack.pop_back()!)
        }
    }

    public static func is_operator(c: String): Bool {
        return ["+", "-", "*", "/", "(", ")", "%"].contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        var cur_mapped = cur
        var peek_mapped = peek

        if cur == "%" {
            cur_mapped = "/"
        }
        if peek == "%" {
            peek_mapped = "/"
        }

        let cur_priority = operat_priority[Int(cur_mapped.first_char().to_ascii() - 40)]
        let peek_priority = operat_priority[Int(peek_mapped.first_char().to_ascii() - 40)]

        return peek_priority >= cur_priority
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        switch current_op {
        case "+":
            return first_value + second_value
        case "-":
            return first_value - second_value
        case "*":
            return first_value * second_value
        case "/":
            return first_value / second_value
        case "%":
            return first_value % second_value
        default:
            fatal_error("Unexpected operator: \(current_op)")
        }
    }

    public static func transform(expression: String): String {
        let pattern = Regex("\\s+")
        var expr = expression.replace(pattern, "")
        expr = expr.replace("=$", "")
        let arr = expr.to_char_array().map { String($0) }
        var result = ArrayList<String>()

        for (i, c) in arr.enumerated() {
            if c == "-" {
                if i == 0 {
                    result.append("~")
                } else {
                    let prev_c = arr[i - 1]
                    if ["+", "-", "*", "/", "(", "E", "e"].contains(prev_c) {
                        result.append("~")
                    } else {
                        result.append(c)
                    }
                }
            } else {
                result.append(c)
            }
        }

        if result.first() == "~" && result.size() > 1 && result[1] == "(" {
            result[0] = "-"
            return "0" + result.join()
        } else {
            return result.join()
        }
    }
}

import std.collection.ArrayList
