    public init() {
        this.employees = HashMap<Int64, Employee>()
    }

    public func add_employee(employee_id: Int64, name: String, position: String, department: String, salary: Int64): Bool {
        if this.employees.contains_key(key: employee_id) {
            return false
        } else {
            this.employees[employee_id] = Employee(name: name, position: position, department: department, salary: salary)
            return true
        }
    }

    public func remove_employee(employee_id: Int64): Bool {
        if this.employees.contains_key(key: employee_id) {
            this.employees.remove(key: employee_id)
            return true
        } else {
            return false
        }
    }

    public func update_employee(employee_id: Int64, employee_info: HashMap<String, Any>): Bool {
        if !this.employees.contains_key(key: employee_id) {
            return false
        }
        var employee = this.employees[employee_id]!
        for (key, value) in employee_info.items() {
            switch key {
                case "name":
                    if let name = value as? String {
                        employee.name = name
                    } else {
                        return false
                    }
                case "position":
                    if let position = value as? String {
                        employee.position = position
                    } else {
                        return false
                    }
                case "department":
                    if let department = value as? String {
                        employee.department = department
                    } else {
                        return false
                    }
                case "salary":
                    if let salary = value as? Int64 {
                        employee.salary = salary
                    } else {
                        return false
                    }
                default:
                    return false
            }
        }
        this.employees[employee_id] = employee
        return true
    }

    public func get_employee(employee_id: Int64): Option<Employee> {
        if this.employees.contains_key(key: employee_id) {
            return Option.some(value: this.employees[employee_id]!)
        } else {
            return Option.none()
        }
    }

    public func list_employees(): ArrayList<Employee> {
        var employee_list = ArrayList<Employee>()
        for employee in this.employees.values() {
            employee_list.add(element: employee)
        }
        return employee_list
    }
}

import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let y_interp = ArrayList<Float64>()
        for xi in x_interp {
            var found = false
            for i in range(0, x.size() - 1) {
                if x[i] <= xi && xi <= x[i+1] {
                    let yi = y[i] + (y[i+1] - y[i]) * (xi - x[i]) / (x[i+1] - x[i])
                    y_interp.append(yi)
                    found = true
                    break
                }
            }
            if !found {
                // Handle case where xi is outside the range of x (optional)
                y_interp.append(0.0) // or throw an error
            }
        }
        return y_interp
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let z_interp = ArrayList<Float64>()
        for (xi, yi) in zip(x_interp, y_interp) {
            var found = false
            for i in range(0, x.size() - 1) {
                if x[i] <= xi && xi <= x[i+1] {
                    for j in range(0, y.size() - 1) {
                        if y[j] <= yi && yi <= y[j+1] {
                            let z00 = z[i][j]
                            let z01 = z[i][j+1]
                            let z10 = z[i+1][j]
                            let z11 = z[i+1][j+1]
                            let zi = (z00 * (x[i+1] - xi) * (y[j+1] - yi) +
                                      z10 * (xi - x[i]) * (y[j+1] - yi) +
                                      z01 * (x[i+1] - xi) * (yi - y[j]) +
                                      z11 * (xi - x[i]) * (yi - y[j])) / ((x[i+1] - x[i]) * (y[j+1] - y[j]))
                            z_interp.append(zi)
                            found = true
                            break
                        }
                    }
                    if found {
                        break
                    }
                }
            }
            if !found {
                // Handle case where (xi, yi) is outside the range of (x, y) (optional)
                z_interp.append(0.0) // or throw an error
            }
        }
        return z_interp
    }
}

import std.convert.Parsable
import std.convert.Formattable
