class JobMarketplace {
    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        let job = JobListing(job_title: job_title, company: company, requirements: requirements)
        this.jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        this.jobListings.remove(job)
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        let resume = Resume(name: name, skills: skills, experience: experience)
        this.resumes.add(resume)
    }

    public func withdraw_resume(resume: Resume): Unit {
        this.resumes.remove(resume)
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let matching_jobs = ArrayList<JobListing>()
        for job_listing in this.jobListings {
            let lower_title = job_listing.job_title.lower()
            let lower_criteria = criteria.lower()
            if lower_title.contains(lower_criteria) {
                matching_jobs.add(job_listing)
                continue
            }
            let found_in_reqs = job_listing.requirements.any(|req| req.lower().contains(lower_criteria))
            if found_in_reqs {
                matching_jobs.add(job_listing)
            }
        }
        return matching_jobs
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let applicants = ArrayList<Resume>()
        for resume in this.resumes {
            if JobMarketplace.matches_requirements(resume: resume, requirements: job.requirements) {
                applicants.add(resume)
            }
        }
        return applicants
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        for skill in resume.skills {
            let found = requirements.any(|req| req == skill)
            if !found {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var dataMat = ArrayList<ArrayList<Float64>>()
        for i in 0..<testData.size() {
            var row = ArrayList<Float64>()
            for j in 0..<testData[i].size() {
                row.add(testData[i][j].toFloat64())
            }
            dataMat.add(row)
        }

        var P0: Float64 = 0.0
        for i in 0..<k {
            P0 += dataMat[i][i]
        }

        var xsum = ArrayList<Float64>()
        for i in 0..<k {
            var sum: Float64 = 0.0
            for j in 0..<k {
                sum += dataMat[i][j]
            }
            xsum.add(sum)
        }

        var ysum = ArrayList<Float64>()
        for j in 0..<k {
            var sum: Float64 = 0.0
            for i in 0..<k {
                sum += dataMat[i][j]
            }
            ysum.add(sum)
        }

        var total: Float64 = 0.0
        for i in 0..<k {
            for j in 0..<k {
                total += dataMat[i][j]
            }
        }

        var Pe: Float64 = 0.0
        for j in 0..<k {
            Pe += ysum[j] * xsum[j]
        }
        Pe = Pe / (total * total)

        P0 = P0 / total
        var cohens_coefficient = (P0 - Pe) / (1 - Pe)
        return cohens_coefficient
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var dataMat = ArrayList<ArrayList<Float64>>()
        for i in 0..<testData.size() {
            var row = ArrayList<Float64>()
            for j in 0..<testData[i].size() {
                row.add(testData[i][j].toFloat64())
            }
            dataMat.add(row)
        }

        var ones = ArrayList<Float64>()
        for _ in 0..<k {
            ones.add(1.0)
        }

        var sumTotal: Float64 = 0.0
        var P0: Float64 = 0.0

        for i in 0..<N {
            var rowSum: Float64 = 0.0
            for j in 0..<k {
                rowSum += dataMat[i][j]
            }

            var temp: Float64 = 0.0
            for j in 0..<k {
                temp += dataMat[i][j] * dataMat[i][j]
            }
            temp -= n
            temp = temp / ((n - 1.0) * n)
            P0 += temp

            sumTotal += rowSum
        }

        P0 = P0 / N

        var ysum = ArrayList<Float64>()
        for j in 0..<k {
            var colSum: Float64 = 0.0
            for i in 0..<N {
                colSum += dataMat[i][j]
            }
            ysum.add(colSum / sumTotal)
        }

        var Pe: Float64 = 0.0
        for j in 0..<k {
            Pe += ysum[j] * ysum[j]
        }

        var ans = (P0 - Pe) / (1 - Pe)
        return ans
    }
}

