class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        if data is not Tuple {
            if data is not ArrayList {
                throw "the input must be a tuple or a list of tuples"
            }
        }

        var meanResult: Float64 = 0.0
        var separateResults: ArrayList<Float64> = ArrayList<Float64>()

        if data is Tuple {
            let d = data as Tuple
            let subList = d[0] as ArrayList<Int64>
            let totalNum = d[1] as Int64

            if totalNum == 0 {
                return (0.0, ArrayList<Float64>([0.0]))
            }

            var mr: Float64 = 0.0
            let rankingArray = ArrayList<Float64>()
            for i in 0..<subList.size() {
                rankingArray.add(1.0 / Float64(i + 1))
            }

            for i in 0..<subList.size() {
                if subList[i] == 1 {
                    mr = rankingArray[i]
                    break
                }
            }

            meanResult = mr
            separateResults.add(mr)
            return (meanResult, separateResults)
        } else {
            let dataList = data as ArrayList<Any>
            var sum: Float64 = 0.0

            for item in dataList {
                if item is not Tuple {
                    throw "each item in list must be a tuple"
                }

                let d = item as Tuple
                let subList = d[0] as ArrayList<Int64>
                let totalNum = d[1] as Int64

                if totalNum == 0 {
                    separateResults.add(0.0)
                    continue
                }

                var mr: Float64 = 0.0
                let rankingArray = ArrayList<Float64>()
                for i in 0..<subList.size() {
                    rankingArray.add(1.0 / Float64(i + 1))
                }

                for i in 0..<subList.size() {
                    if subList[i] == 1 {
                        mr = rankingArray[i]
                        break
                    }
                }

                separateResults.add(mr)
                sum += mr
            }

            if separateResults.size() == 0 {
                return (0.0, separateResults)
            }

            meanResult = sum / Float64(separateResults.size())
            return (meanResult, separateResults)
        }
