class ShoppingCart {

    /*
    The class manages items, their prices, quantities, and allows to for add, removie, view items, and calculate the total price.
    */

    let items: HashMap<String, Item>

    public init() {
        /*
        Initialize the items representing the shopping list as an empty dictionary
        */
        items = HashMap<String, Item>()
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        /*
        Add item information to the shopping list items, including price and quantity. The default quantity is 1
        :param item: String, Item to be added
        :param price: Float64, The price of the item
        :param quantity:Int64, The number of items, defaults to 1
        :return:Unit
        >>> shoppingcart = ShoppingCart()
        >>> shoppingcart.add_item("apple", 1.0, quantity: 5)
        this.items = {"apple": Item(1.0, 5)}
        */
        let new_item = Item(price: price, quantity: quantity)
        if items.containsKey(item) {
            items.set(item, new_item)
        } else {
            items.insert(item, new_item)
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        /*
        Subtract the specified quantity of item from the shopping list items
        :param item:String, Item to be subtracted in quantity
        :param quantity:Int64, Quantity to be subtracted
        :return:Unit
        >>> shoppingcart.add_item("apple", 1.0, quantity: 5)
        >>> shoppingcart.remove_item("apple", quantity: 3)
        this.items = {"apple": Item(1.0, 2)}
        */
        if items.containsKey(item) {
            var current = items.get(item)
            let new_quantity = current.quantity - quantity
            if new_quantity <= 0 {
                items.remove(item)
            } else {
                let updated_item = Item(price: current.price, quantity: new_quantity)
                items.set(item, updated_item)
            }
        }
    }

    public func view_items(): HashMap<String, Item> {
        /*
        Return the current shopping list items
        :return:HashMap<String, Item>, the current shopping list items
        >>> shoppingcart.add_item("apple", 1.0, quantity: 5)
        >>> shoppingcart.remove_item("apple", quantity: 3)
        >>> shoppingcart.view_items()
        {"apple":Item(1.0, 2)}
        */
        return items
    }

    public func total_price(): Float64 {
        /*
        Calculate the total price of all items in the shopping list, which is the quantity of each item multiplied by the price
        :return:Float64, the total price of all items in the shopping list
        >>> shoppingcart = ShoppingCart()
        >>> shoppingcart.add_item("apple", 1.0, quantity: 5)
        >>> shoppingcart.add_item("banana", 2.0, quantity: 3)
        >>> shoppingcart.total_price()
        11.0
        */
        var total: Float64 = 0.0
        for (_, value) in items {
            total += value.price * Float64(value.quantity)
        }
        return total
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SignInSystem {

    /*
    This is a class as sigin in system, including adding users, signing in/out, checking sign-in status, and retrieving signed-in/not signed-in users.
    */

    let users: HashMap<String, Bool>

    public init() {
        /*
        Initialize the sign-in system.
        */
        users = HashMap<String, Bool>()
    }

    public func add_user(username: String): Bool {
        /*
        Add a user to the sign-in system if the user wasn't in the this.users.
        And the initial state is false.
        :param username: String, the username to be added.
        :return: Bool, true if the user is added successfully, false if the user already exists.
        >>> signInSystem.add_user("mike")
        true
        >>> signInSystem.add_user("mike")
        false
        */
        if users.containsKey(username) {
            return false
        } else {
            users.put(username, false)
            return true
        }
    }

    public func sign_in(username: String): Bool {
        /*
        Sign in a user if the user was in the this.users and change the state to true.
        :param username: String, the username to be signed in.
        :return: Bool, true if the user is signed in successfully, false if the user does not exist.
        >>> signInSystem.sign_in("mike")
        true
        >>> signInSystem.sign_in("mik")
        false
        */
        if !users.containsKey(username) {
            return false
        } else {
            users.put(username, true)
            return true
        }
    }

    public func check_sign_in(username: String): Bool {
        /*
        Check if a user is signed in.
        :param username: String, the username to be checked.
        :return: Bool, true if the user is signed in, false if the user does not exist or is not signed in.
        >>> signInSystem.check_sign_in("jack")
        false
        >>> signInSystem.add_user("jack")
        >>> signInSystem.check_sign_in("jack")
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.check_sign_in("jack")
        true
        */
        if !users.containsKey(username) {
            return false
        } else {
            return users.get(username)
        }
    }

    public func all_signed_in(): Bool {
        /*
        Check if all users are signed in.
        :return: Bool, true if all users are signed in, false otherwise.
        >>> signInSystem.add_user("jack")
        true
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.all_signed_in()
        true
        */
        for (_, v) in users {
            if !v {
                return false
            }
        }
        return true
    }

    public func all_not_signed_in(): ArrayList<String> {
        /*
        Get a list of usernames that are not signed in.
        :return: ArrayList<String>, a list of usernames that are not signed in.
        >>> signInSystem = SignInSystem()
        >>> signInSystem.add_user("a")
        true
        >>> signInSystem.add_user("b")
        true
        >>> signInSystem.all_not_signed_in()
        ['a', 'b']
        */
        let result = ArrayList<String>()
        for (k, v) in users {
            if !v {
                result.add(k)
            }
        }
        return result
    }
}

import std.collection.ArrayList
import std.random.Random

class Snake {

    /*
    The class is a snake game, with allows snake to move and eat food, and also enables to reset, and generat a random food position.
    */

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        /*
        Initialize the length of the snake, screen width, screen height, block size, snake head position, score, and food position.
        :param SCREEN_WIDTH: Int64
        :param SCREEN_HEIGHT: Int64
        :param BLOCK_SIZE: Int64, Size of moving units
        :param food_position: ArrayList<Int64>, representing the position(x, y) of food.
        */
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        /*
        Move the snake in the specified direction. If the new position of the snake's head is equal to the position of the food, then eat the food; If the position of the snake's head is equal to the position of its body, then start over, otherwise its own length plus one.
        :param direction: ArrayList<Int64>, representing the direction of movement (x, y).
        :return: Unit
        */
        let cur = this.positions[0]
        let x = direction[0]
        let y = direction[1]
        var newX = (cur[0] + (x * this.BLOCK_SIZE)) % this.SCREEN_WIDTH
        var newY = (cur[1] + (y * this.BLOCK_SIZE)) % this.SCREEN_HEIGHT
        let newPos = ArrayList<Int64>([newX, newY])

        if newX == this.food_position[0] && newY == this.food_position[1] {
            this.eat_food()
        } else {
            if this.positions.size() > 2 {
                let body = ArrayList<ArrayList<Int64>>()
                for i in 2..<this.positions.size() {
                    body.add(this.positions[i])
                }
                if body.contains(newPos) {
                    this.reset()
                    return
                }
            }
            this.positions.insert(0, newPos)
            if this.positions.size() > this.length {
                this.positions.remove_at(this.positions.size() - 1)
            }
        }
    }

    public func random_food_position(): Unit {
        /*
        Randomly generate a new food position, but don't place it on the snake.
        :return: Unit, Change the food position
        */
        let rand = Random()
        var newFood: ArrayList<Int64>
        do {
            let x = rand.next_int(0, this.SCREEN_WIDTH / this.BLOCK_SIZE) * this.BLOCK_SIZE
            let y = rand.next_int(0, this.SCREEN_HEIGHT / this.BLOCK_SIZE) * this.BLOCK_SIZE
            newFood = ArrayList<Int64>([x, y])
        } while (this.positions.contains(newFood))
        this.food_position = newFood
    }

    public func reset(): Unit {
        /*
        Reset the snake to its initial state. Set the length to 1, the snake head position to ((SCREEN_WIDTH/2), (SCREEN_HEIGHT/2)), the score to 0, and randomly generate new food position.
        :return: Unit
        */
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        /*
        Increase the length of the snake by 1 and increase the score by 100. Randomly generate a new food position, but
        don't place it on the snake.
        :return: Unit
        */
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    /*
    The class allows to split sentences, count words in a sentence, and process a text file to find the maximum word count.
    */

    public func split_sentences(sentences_string: String): ArrayList<String> {
        /*
        Split a string into a list of sentences. Sentences end with . or ? and with a space after that. Please note that Mr. also end with . but are not sentences.
        :param sentences_string: String, string to split
        :return: ArrayList<String>, split sentence list
        >>> ss = SplitSentence()
        >>> ss.split_sentences("aaa aaaa. bb bbbb bbb? cccc cccc. dd ddd?")
        ['aaa aaaa.', 'bb bbbb bbb?', 'cccc cccc.', 'dd ddd?']
        */
        let pattern = Regex("(?<!\\w\\.\\w.)(?<![A-Z][a-z]\\.)(?<=\\.|\\?)\\s")
        let matches = pattern.split(sentences_string)
        let sentences = ArrayList<String>()
        for match in matches {
            sentences.add(match.group())
        }
        return sentences
    }

    public func count_words(sentence: String): Int64 {
        /*
        Count the number of words in a sentence. Note that words are separated by spaces and that punctuation marks and numbers are not counted as words.
        :param sentence:String, sentence to be counted, where words are separated by spaces
        :return:Int64, number of words in the sentence
        >>> ss.count_words("abc def")
        2
        */
        let cleaned = Regex("[^a-zA-Z\\s]").replace_all(sentence, "")
        let words = cleaned.split("\\s+").filter { !it.trim().isEmpty() }
        return Int64(words.count)
    }

    public func process_text_file(sentences_string: String): Int64 {
        /*
        Given a text, return the number of words in the longest sentence
        :param sentences_string: String, undivided long sentence
        :return:Int64, the number of words in the longest sentence
        >>> ss.process_text_file("aaa aaaa. bb bbbb bbb? cccc ccccccc cc ccc. dd ddd?")
        4
        */
        let sentences = self.split_sentences(sentences_string: sentences_string)
        var max_count: Int64 = 0
        for sentence in sentences {
            let count = self.count_words(sentence: sentence)
            if count > max_count {
                max_count = count
            }
        }
        return max_count
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class SQLGenerator {

    let table_name: String

    public init(table_name: String) {
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        let fields_str = if fields.isSome {
            fields.unwrap.join(", ")
        } else {
            "*"
        }
        let sql = "SELECT {fields_str} FROM {table_name}"
            .replace("{fields_str}", fields_str)
            .replace("{table_name}", this.table_name)
        if condition.isSome {
            return sql + " WHERE " + condition.unwrap + ";"
        } else {
            return sql + ";"
        }
    }

    public func insert(data: HashMap<String, String>): String {
        let fields = data.keys.join(", ")
        let values = data.values.map(v => "'" + v + "'").join(", ")
        return "INSERT INTO {table_name} ({fields}) VALUES ({values})"
            .replace("{table_name}", this.table_name)
            .replace("{fields}", fields)
            .replace("{values}", values) + ";"
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        let set_clause = data.map((k, v) => "{k} = '{v}'")
            .join(", ")
            .replace("{k}", _)
            .replace("{v}", _)
        return "UPDATE {table_name} SET {set_clause} WHERE {condition}"
            .replace("{table_name}", this.table_name)
            .replace("{set_clause}", set_clause)
            .replace("{condition}", condition) + ";"
    }

    public func delete(condition: String): String {
        return "DELETE FROM {table_name} WHERE {condition}"
            .replace("{table_name}", this.table_name)
            .replace("{condition}", condition) + ";"
    }

    public func select_female_under_age(age: Int64): String {
        let condition = "age < {age} AND gender = 'female'".replace("{age}", age.toString())
        return this.select(condition: Some(condition))
    }

    public func select_by_age_range(min_age: Int64, max_age: Int64): String {
        let condition = "age BETWEEN {min_age} AND {max_age}"
            .replace("{min_age}", min_age.toString())
            .replace("{max_age}", max_age.toString())
        return this.select(condition: Some(condition))
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        var columns_str: String
        if (columns[0] == "*") {
            columns_str = "*"
        } else {
            columns_str = columns.join(", ")
        }
        var query = "SELECT " + columns_str + " FROM " + table
        if (where_condition != None) {
            var conditions = ArrayList<String>()
            var where_map = where_condition.unwrap()
            for pair in where_map {
                conditions.append(pair.key + "='" + pair.value + "'")
            }
            query += " WHERE " + conditions.join(" AND ")
        }
        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        var keys = ArrayList<String>()
        var values = ArrayList<String>()
        for pair in data {
            keys.append(pair.key)
            values.append("'" + pair.value + "'")
        }
        var query = "INSERT INTO " + table + " (" + keys.join(", ") + ") VALUES (" + values.join(", ") + ")"
        return query
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "DELETE FROM " + table
        if (where_condition != None) {
            var conditions = ArrayList<String>()
            var where_map = where_condition.unwrap()
            for pair in where_map {
                conditions.append(pair.key + "='" + pair.value + "'")
            }
            query += " WHERE " + conditions.join(" AND ")
        }
        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        var update_pairs = ArrayList<String>()
        for pair in data {
            update_pairs.append(pair.key + "='" + pair.value + "'")
        }
        var query = "UPDATE " + table + " SET " + update_pairs.join(", ")
        if (where_condition != None) {
            var conditions = ArrayList<String>()
            var where_map = where_condition.unwrap()
            for pair in where_map {
                conditions.append(pair.key + "='" + pair.value + "'")
            }
            query += " WHERE " + conditions.join(" AND ")
        }
        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted = data.clone()
        sort(sorted)
        let n = sorted.size()
        if n % 2 == 1 {
             return sorted.get(n / 2)
        } else {
            let x = sorted.get(n / 2 - 1)
            let y = sorted.get(n / 2)
            return (x + y) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for value in data {
            let count = counts.get(value).orElse(0)
            counts.put(value, count + 1)
        }
        let maxCount = counts.values().max().orElse(0)
        let modes = ArrayList<Int64>()
        for (key, value) in counts {
            if value == maxCount {
                modes.add(key)
            }
        }
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size()
        if n != y.size() || n == 0 {
            return Option.none()
        }

        let sumX = x.fold(0, {acc, val -> acc + val})
        let sumY = y.fold(0, {acc, val -> acc + val})
        let meanX = sumX / n
        let meanY = sumY / n

        let numerator = x.zip(y).fold(0, {acc, pair -> 
            let (xi, yi) = pair
            acc + (xi - meanX) * (yi - meanY)
        })

        let sumXSquared = x.fold(0, {acc, val -> acc + (val - meanX) ** 2})
        let sumYSqared = y.fold(0, {acc, val -> acc + (val - meanY) ** 2})
        let denominator = sqrt(sumXSquared * sumYSqared)

        if denominator == 0 {
            return Option.none()
        } else {
            return Option.some(numerator / denominator)
        }
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size()
        if n == 0 {
            return Option.none()
        }
        let sum = data.fold(0, {acc, val -> acc + val})
        return Option.some(sum / n)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let cols = data.size()
        if cols == 0 || data.get(0).size() == 0 {
            return ArrayList<ArrayList<Float64>>()
        }
        let rows = data.get(0).size()
        let matrix = ArrayList<ArrayList<Float64>>()
        for i in 0..cols {
            let row = ArrayList<Float64>()
            for j in 0..cols {
                let columnI = ArrayList<Int64>()
                let columnJ = ArrayList<Int64>()
                for k in 0..rows {
                    columnI.add(data.get(i).get(k))
                    columnJ.add(data.get(j).get(k))
                }
                let corr = correlation(columnI, columnJ)
                row.add(corr.orElse(0.0))
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size()
        if n < 2 {
            return Option.none()
        }

        let mean = mean(data)
        if !mean.isPresent() {
            return Option.none()
        }

        let variance = data.fold(0, {acc, val -> 
            acc + (val - mean.get()) ** 2 
        }) / (n - 1)
        return Option.some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let n = data.size()
        if n == 0 {
            return Option.none()
        }

        let mean = mean(data)
        let std = standard_deviation(data)

        if !mean.isPresent() || !std.isPresent() || std.get() == 0 {
            return Option.none()
        }

        let zScores = ArrayList<Float64>()
        for value in data {
            let z = (value - mean.get()) / std.get()
            zScores.add(z)
        }
        return Option.some(zScores)
    }
}

