class Warehouse {

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        this.inventory = HashMap<Int64, Product>()
        this.orders = HashMap<Int64, Order>()
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        if this.inventory.contains(key: product_id) {
            let product: Product = this.inventory[product_id]!
            product.quantity += quantity
        } else {
            let new_product: Product = Product(name: name, quantity: quantity)
            this.inventory[product_id] = new_product
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        if this.inventory.contains(key: product_id) {
            let product: Product = this.inventory[product_id]!
            product.quantity += quantity
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        if this.inventory.contains(key: product_id) {
            let product: Product = this.inventory[product_id]!
            return Some(product.quantity)
        } else {
            return None()
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        match this.get_product_quantity(product_id: product_id) {
            Some(inventory_quantity) => {
                if inventory_quantity >= quantity {
                    this.update_product_quantity(product_id: product_id, quantity: -quantity)
                    let new_order: Order = Order(product_id: product_id, quantity: quantity, status: "Shipped")
                    this.orders[order_id] = new_order
                    return true
                } else {
                    return false
                }
            },
            None() => {
                return false
            }
        }
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        if this.orders.contains(key: order_id) {
            let order: Order = this.orders[order_id]!
            order.status = status
            return true
        } else {
            return false
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        if this.orders.contains(key: order_id) {
            let order: Order = this.orders[order_id]!
            return Some(order.status)
        } else {
            return None()
        }
    }
}

